  width: var(--_ib-size);
  height: var(--_ib-size);
  padding: 0;
  border: 0;
  border-radius: var(--radius-200, 8px);
  background: transparent;
  color: inherit;
  cursor: pointer;
  transition: background var(--transition-fast, 0.15s ease);
  -webkit-appearance: none;
  appearance: none;
}
.cbf-hero {
  position: relative;
  height: 640px;
  background: #1d3c5d url(assets/hero.webp) center 40% / cover no-repeat;
  display: flex;
  align-items: flex-end;
}
.cbf-hero__title {
  position: relative;
  z-index: 1;
  margin: 0 0 36px 61px;
}
.cbf-hero__line {
  margin: 0;
  color: #fff;
  font-family: var(--font-display);
  font-size: 64px;
  line-height: 64px;
  font-weight: var(--font-weight-regular);
  font-feature-settings:
    "liga" off,
    "clig" off;
}
.cbf-hero__line--strong {
  font-weight: var(--font-weight-semibold);
}
.cbf-hero:after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, #13273e00 45%, #13273e73);
}
.cbf-container {
  width: 100%;
  max-width: var(--cbf-container-max, 1556px);
  margin-inline: auto;
  padding-inline: var(--spacing-600);
}
.cbf-about {
  display: grid;
  grid-template-columns: 2fr 3fr;
  gap: var(--spacing-600);
  align-items: start;
  padding-block: var(--spacing-800);
}
.cbf-stat-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--spacing-400);
}
.cbf-stat-tile {
  aspect-ratio: 1 / 1;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-200);
  align-items: center;
  justify-content: center;
  background: var(--color-primary-subtle);
  border: 2px solid var(--color-primary-border);
}
.cbf-stat-tile__num {
  font-family: var(--font-display);
  font-weight: var(--font-weight-semibold);
  font-size: 60px;
  line-height: 60px;
  color: var(--color-text-primary);
}
.cbf-stat-tile__label {
  font-size: 18px;
  font-weight: var(--font-weight-semibold);
  text-align: center;
}
.cbf-about__copy {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-400);
}
.cbf-about__title {
  margin: 0;
  font-size: 28px;
  font-weight: var(--font-weight-medium);
  line-height: 40px;
}
.cbf-about__body {
  margin: 0;
  font-size: 24px;
  font-weight: var(--font-weight-regular);
  line-height: 32px;
}
.cbf-glance {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--spacing-500);
  padding-block: var(--spacing-600);
}
.cbf-pg-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--spacing-600);
}
.cbf-pg-header__title {
  margin: 0;
  font-family: var(--font-display);
  font-weight: var(--font-weight-semibold);
  font-size: 40px;
  line-height: 40px;
}
.cbf-control-pill {
  display: flex;
  align-items: center;
  gap: var(--spacing-500);
  padding: var(--spacing-300) var(--spacing-500);
  background: var(--color-primary-subtle);
  border: 1px solid var(--color-primary-border);
  border-radius: var(--radius-100);
}
.cbf-control-pill__btn {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-200);
  font-size: 16px;
  font-weight: var(--font-weight-bold);
  font-family: var(--font-sans);
  color: var(--color-primary);
  background: none;
  border: 0;
  cursor: pointer;
}
.cbf-control-pill__btn .esa-icon {
  width: 12px;
  height: 12px;
}
.cbf-control-pill__btn .esa-icon svg {
  width: 12px;
  height: 12px;
}
.cbf-control-pill__divider {
  width: 1px;
  height: 16px;
  background: var(--color-border);
}
.cbf-svg {
  width: 12px;
  height: 12px;
  display: block;
  flex: none;
}
.cbf-glance__chart {
  width: 100%;
}
.cbf-glance__chart img {
  width: 100%;
  height: auto;
}
.cbf-glance__meta {
  width: 100%;
  display: flex;
  justify-content: flex-end;
  padding-block: var(--spacing-200);
  border-top: 1px solid var(--color-border);
  font-size: 14px;
}
.cbf-glance__meta span {
  color: var(--color-text-muted);
}
.cbf-glance__meta a {
  color: var(--color-primary);
  text-decoration: underline;
}
.cbf-footer {
  background: var(--color-primary);
  color: var(--color-text-inverse, #fff);
}
.cbf-footer__inner {
  display: flex;
  flex-direction: column;
}
.cbf-footer__nav {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: var(--spacing-650);
  align-items: start;
  padding: var(--spacing-700) var(--spacing-600) 0;
}
.cbf-footer__cols {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(11.25rem, 1fr));
  gap: var(--spacing-650);
}
.esa-link-column {
  color: inherit;
}
.esa-link-column__head {
  display: block;
  margin: 0 0 var(--spacing-100, 4px);
  font-size: var(--type-size-200, 1rem);
  font-weight: var(--font-weight-medium, 500);
  color: inherit;
  text-decoration: none;
}
.esa-link-column__rule {
  height: 1px;
  border: 0;
  margin: 0 0 var(--spacing-200, 8px);
  background: color-mix(in srgb, currentColor 40%, transparent);
}
.esa-link-column__list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.esa-link-column__list li {
  font-size: var(--type-size-150, 0.875rem);
  line-height: 22px;
  margin-bottom: var(--spacing-100, 4px);
}
.cbf-bpa-logo {
  flex: none;
  align-self: start;
  max-width: 254px;
}
.cbf-bpa-logo__img {
  width: 100%;
  height: auto;
}
.cbf-footer__meta {
  display: flex;
  justify-content: flex-end;
  gap: var(--spacing-400);
  padding: 0 var(--spacing-600) var(--spacing-700);
  font-size: 12px;
}
.cbf-footer__meta a {
  text-decoration: underline;
}
